package com.andye.warmod.item;import com.andye.warmod.block.*;import com.andye.warmod.block.entity.*;import com.andye.warmod.item.component.*;import com.andye.warmod.radar.display.*;import java.util.function.Consumer;import net.minecraft.network.chat.Component;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.component.TooltipDisplay;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.level.Level;
public final class RadarLinkingToolItem extends Item{public RadarLinkingToolItem(Properties p){super(p);}@Override public InteractionResult useOn(UseOnContext c){if(c.getLevel().isClientSide()||!(c.getPlayer()instanceof ServerPlayer player))return InteractionResult.SUCCESS;ItemStack stack=c.getItemInHand();var state=c.getLevel().getBlockState(c.getClickedPos());if(player.isShiftKeyDown()&&state.is(ModBlocks.RADAR_STATION)){RadarStationBlockEntity station=RadarStationBlock.resolve(c.getLevel(),c.getClickedPos(),state);if(station==null||!RadarStationStructure.complete((ServerLevel)c.getLevel(),station.getBlockPos(),station.facing())){player.sendSystemMessage(Component.literal("Radar Station is incomplete"));return InteractionResult.FAIL;}stack.set(ModDataComponents.LINKED_RADAR_STATION,new LinkedRadarStation(c.getLevel().dimension(),station.getBlockPos(),station.radarId()));player.sendSystemMessage(Component.literal("Radar Linking Tool linked to station "+station.radarId().toString().substring(0,8)));return InteractionResult.SUCCESS_SERVER;}if(state.is(ModBlocks.RADAR_DISPLAY_PANEL)){RadarDisplayStructure display=RadarDisplayStructure.resolve(c.getLevel(),c.getClickedPos());if(!display.valid()){player.sendSystemMessage(Component.literal("Display must form a filled square from 1x1 to 10x10"));return InteractionResult.FAIL;}LinkedRadarStation linked=stack.get(ModDataComponents.LINKED_RADAR_STATION);if(linked==null||!linked.dimension().equals(c.getLevel().dimension()))return fail(player,"No same-dimension Radar Station linked");if(display.controller().distSqr(linked.centre())>RadarDisplayConstants.LINK_DISTANCE_BLOCKS*RadarDisplayConstants.LINK_DISTANCE_BLOCKS)return fail(player,"Radar Station is farther than 100 blocks");if(!(c.getLevel().getBlockEntity(linked.centre())instanceof RadarStationBlockEntity station)||!station.radarId().equals(linked.radarId())||!RadarStationStructure.complete((ServerLevel)c.getLevel(),linked.centre(),station.facing()))return fail(player,"Linked Radar Station is stale or incomplete");RadarDisplayLink link=new RadarDisplayLink(linked.dimension(),linked.centre(),linked.radarId());RadarDisplayManager.applyLink((ServerLevel)c.getLevel(),display,link);player.sendSystemMessage(Component.literal("Radar display linked: "+display.size()+"x"+display.size()+", range "+RadarDisplayConstants.radius(display.size())));return InteractionResult.SUCCESS_SERVER;}return InteractionResult.PASS;}@Override public InteractionResult use(Level l,Player p,InteractionHand h){if(l.isClientSide())return InteractionResult.SUCCESS;if(p.isShiftKeyDown()){p.getItemInHand(h).remove(ModDataComponents.LINKED_RADAR_STATION);p.sendSystemMessage(Component.literal("Radar Station link cleared"));return InteractionResult.SUCCESS_SERVER;}return InteractionResult.PASS;}@Override public boolean isFoil(ItemStack s){return s.has(ModDataComponents.LINKED_RADAR_STATION);}@Override public void appendHoverText(ItemStack s,TooltipContext c,TooltipDisplay d,Consumer<Component>b,TooltipFlag f){LinkedRadarStation link=s.get(ModDataComponents.LINKED_RADAR_STATION);b.accept(Component.literal(link==null?"Station: Not linked":"Station: "+link.radarId().toString().substring(0,8)));}private static InteractionResult fail(Player p,String m){p.sendSystemMessage(Component.literal(m));return InteractionResult.FAIL;}}
